void handleRoutingData(uint64_t connId, RoutingData& routingData) {
    auto pipeline = getRoutingPipeline(connId);
    if (!pipeline) {
        LOG(INFO) << "Pipeline not found for connection ID: " << connId;
        return;
    }

    pipeline->pauseTransport();

    uint32_t acceptorId = hashRoutingData(routingData) % NUM_ACCEPTORS;
    Acceptor* acceptor = getAcceptor(acceptorId);

    if (!acceptor) {
        LOG(ERROR) << "Acceptor not found for ID: " << acceptorId;
        return;
    }

    // Switch to the acceptor's thread
    std::lock_guard<std::mutex> lock(acceptor->mutex_);

    // Attach the socket to the acceptor's event base
    boost::asio::ip::tcp::socket socket = pipeline->releaseSocket();
    socket.non_blocking(true);
    socket.set_option(boost::asio::ip::tcp::no_delay(true));

    // Create a new pipeline with the routing data
    auto newPipeline = createPipelineWithRoutingData(routingData, acceptor->eventBase_);

    // Add a new server connection to the acceptor
    acceptor->addConnection(newPipeline);

    newPipeline->activateTransport();
    newPipeline->readBufferedBytes();
}

void handleRoutingData(uint64_t connId, RoutingData& routingData) {
