    pipeline->pauseTransport();

    std::size_t hash = std::hash<std::string>()(routingData.toString());
    Acceptor* newAcceptor = selectAcceptor(hash);

    newAcceptor->getEventBase()->runInEventBaseThread([connId, routingData, newAcceptor, pipeline] {
