        socket->attachEventBase(newAcceptor->getEventBase());

        auto newPipeline = newRoutingPipeline(routingData);
        newPipeline->addHandler(new ServerConnectionHandler());

        newPipeline->activateTransport();
        newPipeline->readBufferedBytes();
